class CacheEffect(BaseModel):
    """
    Used within an OpenAPI path or path operation extension (e.g., x-cache-behaviour) to describe a single cache interaction that occurs when the operation is executed. Defines which cache contract is affected and how it is read or mutated.
    Expected validation rules:

      - all bindings in a CacheEffect MUST have the same actor
        - and if using machine mode, MUST have the same language

      - If action == `read`:
        - `keyReadSource` SHOULD be present (MUST if contract key has params)

      - If action ∈ `{upsert, set, set_if_absent}`:
        - `keyWriteSource` MUST be present
        - `valueWriteSource` MUST be present

      - If action ∈ `{delete, refresh, increment}`:
        - `keyWriteSource` MUST be present

    validation Rationale:
      Cache contracts define key and value *shapes*,
      but cache effects must define concrete runtime bindings
      to ensure deterministic behavior.

    """

    targetContract: CacheEffectTargetContract
    action: CacheEffectAction
    keyReadSource: Optional[CacheEffectKeyReadSource] = None
    keyWriteSource: Optional[CacheEffectKeyWriteSource] = None
    valueReadSource: Optional[CacheEffectValueReadSource] = None
    valueWriteSource: Optional[CacheEffectValueWriteSource] = None
    ttlOverride: Annotated[
        Optional[CacheTtl],
        Field(description='Optional TTL override for this cache effect.\n'),
    ] = None
    encodingOverride: Annotated[
        Optional[CacheEncoding],
        Field(
            description='Optional cache value encoding format override.\nAllow hash override for:\n- counters/rate-limits - session-like objects where only one field changes frequently - hot paths where rewrite cost matters\n'
        ),
    ] = None
    guarantees: Optional[CacheEffectGuarantees] = None
    preconditions: Optional[CacheEffectPreconditions] = None
    enforcementOverride: Annotated[
        Optional[CacheEnforcementExpectations],
        Field(
            description='Only applicable when action: read.\nOptional per-effect override for enforcement expectations defined on the cache contract.\nIntended primarily for read effects where specific endpoints may tolerate cache miss.\n'
        ),
    ] = None


