class LinkRef(BaseModel):
    """
    A pointer to an instance owned by another artifact. Exactly one artifact owns a given
    element instance and others link to it, so a link names an instance rather than an element.
    A link is not an instance record: a pointer has no asserting party, status or observation
    time of its own.

    """

    model_config = ConfigDict(
        extra='forbid',
    )

    artifactId: ArtifactId
    instanceId: InstanceId


class ArtifactLinks(RootModel[Optional[Dict[str, List[LinkRef]]]]):
    """
    A map from element code to the instances this artifact links rather than owns.

    """

    root: Optional[Dict[str, List[LinkRef]]] = None


